            postMethod.setRequestHeader("Cookie", cookieToString(cookies));
            // 设置HTTP代理IP和端口
            httpClient.getHostConfiguration().setProxy(hostIp, hostIpPort);
            if (params != null) {
                for (int i = 0; i < params.size(); i++) {
